  have h_main : min (min a b) c = -4 := by
    have h₂ : a ∣ 32 := by
      use b * c
      linarith
    have h₃ : b ∣ 32 := by
      use a * c
      nlinarith
    have h₄ : c ∣ 32 := by
      use a * b
      nlinarith
    -- We now check all possible values of a, b, and c that divide 32 and satisfy a * b * c = 32
    have h₅ : a = -4 ∨ a = -2 ∨ a = -1 ∨ a = 1 ∨ a = 2 ∨ a = 4 ∨ a = 8 ∨ a = 16 ∨ a = 32 ∨ a = -32 ∨ a = -16 ∨ a = -8 ∨ a = -4 ∨ a = 4 ∨ a = 8 ∨ a = 16 ∨ a = 32 := by
      -- a divides 32, so a is a divisor of 32
      have h₅ : a ∣ 32 := h₂
      have h₆ : a = -32 ∨ a = -16 ∨ a = -8 ∨ a = -4 ∨ a = -2 ∨ a = -1 ∨ a = 1 ∨ a = 2 ∨ a = 4 ∨ a = 8 ∨ a = 16 ∨ a = 32 := by
        rw [← Int.natAbs_dvd_natAbs] at h₅
        -- Convert to natural number divisibility
        have h₇ : a.natAbs ∣ 32 := by simpa [Int.natAbs] using h₅
        -- Find all divisors of 32
        have h₈ : a.natAbs = 1 ∨ a.natAbs = 2 ∨ a.natAbs = 4 ∨ a.natAbs = 8 ∨ a.natAbs = 16 ∨ a.natAbs = 32 := by
          have h₉ : a.natAbs ∣ 32 := h₇
          have h₁₀ : a.natAbs ≤ 32 := Nat.le_of_dvd (by norm_num) h₉
          interval_cases a.natAbs <;> norm_num at h₉ ⊢ <;> omega
        rcases h₈ with (h₈ | h₈ | h₈ | h₈ | h₈ | h₈) <;>
          (try omega) <;>
          (try {
            have h₉ : a = 1 ∨ a = -1 := by
              omega
            rcases h₉ with (h₉ | h₉) <;> simp_all [Int.natAbs] <;> omega
          }) <;>
          (try {
            have h₉ : a = 2 ∨ a = -2 := by
              omega
            rcases h₉ with (h₉ | h₉) <;> simp_all [Int.natAbs] <;> omega
          }) <;>
          (try {
            have h₉ : a = 4 ∨ a = -4 := by
              omega
            rcases h₉ with (h₉ | h₉) <;> simp_all [Int.natAbs] <;> omega
          }) <;>
          (try {
