            rcases h₉ with (h₉ | h₉) <;> simp_all [Int.natAbs] <;> omega
          }) <;>
          (try {
            have h₉ : a = 32 ∨ a = -32 := by
              omega
            rcases h₉ with (h₉ | h₉) <;> simp_all [Int.natAbs] <;> omega
          })
      rcases h₆ with (h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆ | h₆) <;> simp_all [Int.natAbs] <;> omega
